// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));

        // initialize: test contract becomes owner
        c.initialize();

        // hand ownership to a fuzzed actor
        vm.prank(address(this));
        c.transferOwnership(actor);
        require(c.owner() == actor, "setup");

        address oldOwner = c.owner();

        vm.prank(actor);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: ownership either moves exactly to newOwner (call succeeded,
        // nonzero newOwner) or stays unchanged (call reverted, e.g. zero newOwner).
        assertTrue(c.owner() == (ok ? newOwner : oldOwner));
    }
}
